<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
$product=get_query_var('ip_product'); if(!$product instanceof WC_Product){return;}
?><article class="ip-product-card"><a class="product-image" href="<?php echo esc_url(get_permalink($product->get_id())); ?>"><?php echo wp_kses_post($product->get_image('woocommerce_thumbnail',array('loading'=>'lazy'))); ?><?php if($product->is_on_sale()):?><span class="sale-badge"><?php esc_html_e('Offer','illuminated-path'); ?></span><?php endif;?></a><div class="product-card-body"><div class="product-card-meta"><?php echo wp_kses_post(wc_get_product_category_list($product->get_id(),', ')); ?></div><h3><a href="<?php echo esc_url(get_permalink($product->get_id())); ?>"><?php echo esc_html($product->get_name()); ?></a></h3><div class="product-card-bottom"><div class="product-price"><?php echo wp_kses_post($product->get_price_html()); ?></div><?php if($product->is_purchasable()&&$product->is_in_stock()):?><a class="card-cart" href="<?php echo esc_url($product->add_to_cart_url()); ?>" data-quantity="1" data-product_id="<?php echo esc_attr((string)$product->get_id()); ?>" aria-label="<?php echo esc_attr($product->add_to_cart_description()); ?>">+</a><?php endif;?></div></div></article>
